function managementCheck(node){if(node?.transport==='ssh')return node.status==='reachable'?'SSH authenticated':'SSH port open';if(node?.transport==='esxi-soap'||node?.device_type==='esxi')return node?.probe_status==='hypervisor-authenticated'?'ESXi SOAP/API authenticated':'ESXi SOAP/API detected';if(node?.connection_mode==='agent'&&node.status==='reachable')return 'Agent connected';if(node?.transport==='wmi'){if(node.probe_status==='rpc-authenticated')return 'RPC authenticated';if(node.probe_status==='wmi-authenticated')return 'WMI credential authenticated';return 'RPC not verified'}if(node?.transport==='netsh')return node.status==='reachable'?'SMB/netsh authenticated':'SMB service open';if(['winrm','winrms'].includes(node?.transport))return node.status==='reachable'?'WinRM authenticated':'WinRM port open';return 'No management connection'}
function closeContextMenu(){contextMenu.value=null}
function openContextMenu(event,node){
  event.preventDefault();event.stopPropagation()
  const rect=event.currentTarget.getBoundingClientRect()
  const x=Math.max(8,Math.min(event.clientX||rect.left,window.innerWidth-230))
  const y=Math.max(8,Math.min(event.clientY||rect.bottom,window.innerHeight-195))
  contextMenu.value={node,x,y}
  nextTick(()=>contextMenuEl.value?.querySelector('button')?.focus({preventScroll:true}))
}
