const isSsh=node=>node?.transport==='ssh'||node?.management_type==='ssh'
const isManaged=node=>isSsh(node)||isSnmp(node)||isEsxi(node)||node?.connection_mode==='agent'||node?.agent_id||node?.training?.status==='active'||(node?.firewall_state==='enforcing'&&!(node?.agent_required&&!node?.agent_id))||node?.managementVerification?.status==='reachable'
