async function loadNodes(){
  const params=new URLSearchParams({page:String(assetPage.value),pageSize:String(assetPageSize.value),search:search.value,filter:assetFilter.value,sort:assetSort.value,direction:assetSortDir.value})
  try{const result=await api(`/nodes?${params}`);nodes.value=result.items||[];assetTotal.value=Number(result.total||0);assetTotalPages.value=Number(result.totalPages||1);if(assetPage.value>assetTotalPages.value){assetPage.value=assetTotalPages.value;return loadNodes()}}catch(e){error.value=`Inventory refresh incomplete: ${e.message}`}
}
