function toggleTriageSelection(nodeId,event){const ids=new Set(triageSelectedIds.value);if(event.target.checked)ids.add(nodeId);else ids.delete(nodeId);triageSelectedIds.value=[...ids]}
function toggleTriagePage(event){const ids=new Set(triageSelectedIds.value);for(const node of triageNodes.value){if(event.target.checked)ids.add(node.id);else ids.delete(node.id)}triageSelectedIds.value=[...ids]}
function clearTriageSelection(){triageSelectedIds.value=[];triageBulkAction.value='';triageBulkCredentialId.value=''}
function triageActionNeedsCredential(){return triageBulkAction.value==='assign_and_retry'}
async function runBulkTriage(){
  if(!triageSelectedIds.value.length||!triageBulkAction.value)return
  if(triageActionNeedsCredential()&&!triageBulkCredentialId.value){error.value='Choose a credential before retrying enrollment.';return}
  triageBulkBusy.value=true;error.value='';message.value=''
  try{
    const result=await api('/nodes/triage/bulk',{method:'POST',body:{nodeIds:triageSelectedIds.value,action:triageBulkAction.value,credentialId:triageBulkCredentialId.value||undefined}})
    const failures=(result.results||[]).filter(item=>!item.success)
    message.value=triageBulkAction.value==='assign_and_retry'?`Retried ${result.requested} asset${result.requested===1?'':'s'}; ${failures.length} still need attention.`:`Updated ${result.requested} triage asset${result.requested===1?'':'s'}.`
    if(failures.length)error.value=failures.slice(0,3).map(item=>`${item.hostname}: ${item.error||item.probe?.note||'retry failed'}`).join(' · ')
    clearTriageSelection();await loadTriage()
  }catch(cause){error.value=cause.message}
  finally{triageBulkBusy.value=false}
}
async function updateTriage(node,status){busy.value=true;error.value='';try{await api(`/nodes/${node.id}/triage`,{method:'PATCH',body:{status}});message.value=`${node.hostname} marked ${status==='none'?'open':status}`;await loadTriage()}catch(e){error.value=e.message}finally{busy.value=false}}
function flagTriage(node){updateTriage(node,'flagged')}
function clearTriage(node){updateTriage(node,'none')}
function excludeTriage(node){askConfirmation(`Exclude ${node.hostname} from the unmanaged asset queue? You can restore it from the Excluded filter.`,()=>updateTriage(node,'excluded'))}
async function load(){
  const requests=await Promise.allSettled([loadNodes(),loadTriage(),api('/credentials'),api('/node-groups'),api('/settings/training'),canEdit.value?api('/credentials/health'):Promise.resolve({notices:[]})])
  const [,loadedTriage,loadedCredentials,loadedGroups,settings,health]=requests
  if(loadedTriage.status==='rejected'&&!error.value)error.value=`Triage refresh incomplete: ${loadedTriage.reason?.message||'Request failed'}`
  if(loadedCredentials.status==='fulfilled')credentials.value=loadedCredentials.value
  if(loadedGroups.status==='fulfilled')groups.value=loadedGroups.value
  if(settings.status==='fulfilled')trainingDays.value=settings.value.newHostTrainingDays
  if(health.status==='fulfilled')credentialNotices.value=health.value.notices||[]
  const failures=requests.filter(result=>result.status==='rejected').map(result=>result.reason?.message||'Request failed')
  error.value=failures.length?`Inventory refresh incomplete: ${failures.join('; ')}`:''
}
onMounted(load)
