async function testNewNodeConnection(){
  const credentialId=form.value.credentialIds?.[0],host=String(form.value.ip||form.value.fqdn||form.value.hostname||'').trim()
  if(!credentialId||!host){preflightResult.value={success:false,error:'Enter an address and select a Windows credential first.'};preflightKey.value='';return}
  preflightBusy.value=true;preflightResult.value=null;preflightKey.value=''
  try{preflightResult.value=await api(`/credentials/${credentialId}/preflight`,{method:'POST',body:{host,expectedName:form.value.hostname||undefined}});if(preflightResult.value.success)preflightKey.value=preflightFingerprint()}catch(e){preflightResult.value={success:false,error:e.message}}finally{preflightBusy.value=false}
}
async function create(){
  const credentialId=form.value.credentialIds?.[0]
  if(credentialId&&preflightKey.value!==preflightFingerprint()){error.value='Test the selected credential before adding this node.';return}
  busy.value=true;error.value='';try{const node=await api('/nodes',{method:'POST',body:form.value});formOpen.value=false;form.value={hostname:'',fqdn:'',ip:'',credentialIds:[]};preflightResult.value=null;preflightKey.value='';message.value=`${node.hostname} added; ${node.training.days}-day training started`;await load()}catch(e){error.value=e.message}finally{busy.value=false}
}
