  })
}
async function retrain(){if(!selected.value)return;busy.value=true;error.value='';try{const session=await api(`/nodes/${selected.value.id}/training`,{method:'POST',body:{durationDays:Number(retrainDays.value)}});selected.value=await api(`/nodes/${selected.value.id}`);message.value=`Relearning started through ${new Date(session.endsAt).toLocaleString()}`;await load()}catch(e){error.value=e.message}finally{busy.value=false}}
function beginEdit(){if(!selected.value)return;const currentIds=[...(selected.value.credentialIds||[])],esxiId=currentIds.find(id=>esxiCredentials.value.some(credential=>credential.id===id))||'';editForm.value={hostname:selected.value.hostname,fqdn:selected.value.fqdn||'',ip:selected.value.ip||'',deviceType:selected.value.device_type||selected.value.deviceType||'auto',managementType:(selected.value.device_type||selected.value.deviceType)==='esxi'?'api':(selected.value.management_type||selected.value.managementType||(isSnmp(selected.value)?'snmp':'auto')),credentialIds:currentIds.filter(id=>!esxiCredentials.value.some(credential=>credential.id===id)),esxiCredentialId:esxiId};error.value='';detailOpen.value=false;editOpen.value=true}
function onDeviceTypeChange(){if(editForm.value.deviceType==='linux'&&editForm.value.managementType==='auto')editForm.value.managementType='ssh';if(editForm.value.deviceType==='esxi'){editForm.value.managementType='api';if(!editForm.value.esxiCredentialId)editForm.value.esxiCredentialId=esxiCredentials.value[0]?.id||''}}
async function saveEdit(){if(!selected.value)return;busy.value=true;error.value='';try{const credentialIds=[...(editForm.value.credentialIds||[])];if(editForm.value.deviceType==='esxi'&&editForm.value.esxiCredentialId)credentialIds.push(editForm.value.esxiCredentialId);const fields=selected.value.ad_guid?{ip:editForm.value.ip.trim()||null,deviceType:editForm.value.deviceType,managementType:editForm.value.managementType,credentialIds:[...new Set(credentialIds)]}:{hostname:editForm.value.hostname.trim(),fqdn:editForm.value.fqdn.trim()||null,ip:editForm.value.ip.trim()||null,deviceType:editForm.value.deviceType,managementType:editForm.value.managementType,credentialIds:[...new Set(credentialIds)]};await api(`/nodes/${selected.value.id}`,{method:'PATCH',body:fields});selected.value=await api(`/nodes/${selected.value.id}`);editOpen.value=false;detailOpen.value=true;message.value=`${selected.value.hostname} updated`;await load()}catch(e){error.value=e.message}finally{busy.value=false}}
function beginDelete(){deleteConfirmation.value=false;error.value='';detailOpen.value=false;deleteOpen.value=true}
async function deleteNode(){if(!selected.value||!deleteConfirmation.value)return;busy.value=true;error.value='';try{const name=selected.value.hostname;await api(`/nodes/${selected.value.id}`,{method:'DELETE',body:{confirmed:true}});deleteOpen.value=false;detailOpen.value=false;selected.value=null;message.value=`${name} removed from inventory`;await load()}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template><div class="view"><PageHeader eyebrow="ASSETS / WINDOWS NODES" :title="activeTheme==='enterprise'?'Monitored assets':'Node inventory'" description="Onboard, inspect and verify firewall hosts"><button v-if="activeTab==='groups'" class="button primary" @click="openAddGroup"><i class="mdi mdi-plus"></i> Add node group</button><button v-else-if="activeTab==='assets'" class="button primary" @click="openAddNode"><i class="mdi mdi-plus"></i> Add node</button></PageHeader><div v-if="error" class="error-msg">{{error}}</div><div v-if="message" class="success-msg">{{message}}</div><div v-if="onboardingNotice" class="onboarding-notice"><strong>{{onboardingNotice.title}}</strong><p>{{onboardingNotice.summary}}</p><small><b>Remediation:</b> {{onboardingNotice.remediation}}</small></div><div v-if="credentialNotices.length" class="credential-health-notices" role="status"><div v-for="notice in credentialNotices" :key="notice.credentialId" class="credential-health-notice"><div><strong>{{notice.title}}</strong><p>{{notice.summary}}</p><small><b>Affected nodes:</b> {{notice.affectedNodes.map(node=>node.hostname).join(', ')}}</small></div><span class="status failed">{{notice.affectedNodeCount}} nodes</span><small><b>Next step:</b> {{notice.remediation}}</small></div></div><nav class="view-tabs" aria-label="Inventory sections"><button type="button" :class="{active:activeTab==='assets'}" @click="activeTab='assets'">Assets <span>{{assetTotal}}</span></button><button type="button" :class="{active:activeTab==='groups'}" @click="activeTab='groups'">Node groups <span>{{groups.length}}</span></button><button type="button" :class="{active:activeTab==='triage'}" @click="activeTab='triage';loadTriage()">Unmanaged assets <span>{{triageSummary.open}}</span></button></nav><section v-if="activeTab==='assets'" class="panel glass"><div class="panel-title"><div><span class="eyebrow">MANAGED ASSETS</span><h2>{{assetTotal}} nodes</h2></div><div class="table-tools asset-toolbar"><input v-model="search" @input="searchAssets" class="search" placeholder="Search hostname, address, OS" aria-label="Search nodes"><select v-model="assetFilter" @change="searchAssets" aria-label="Filter assets"><option value="all">All assets</option><option value="managed">Managed / learning</option><option value="unmanaged">Unmanaged</option><option value="reachable">Reachable</option><option value="unreachable">Unreachable</option></select><label class="page-size">Rows <select v-model.number="assetPageSize" @change="changeAssetPageSize"><option :value="25">25</option><option :value="50">50</option><option :value="100">100</option></select></label><button class="icon-button" @click="load" title="Refresh"><i class="mdi mdi-refresh"></i></button></div></div><div class="table-wrap"><table class="asset-table"><thead><tr><th><button type="button" class="asset-sort" @click="sortAssets('hostname')">HOSTNAME</button></th><th><button type="button" class="asset-sort" @click="sortAssets('address')">ADDRESS</button></th><th>OS</th><th>MODE</th><th>SOURCE</th><th>FIREWALL</th><th>VERIFY</th><th><button type="button" class="asset-sort" @click="sortAssets('status')">STATUS</button></th><th>LAST SEEN</th><th aria-label="Actions"><span class="sr-only">Actions</span></th></tr></thead><tbody><tr v-for="node in nodes" :key="node.id" @click="select(node)" @contextmenu="openContextMenu($event,node)" @keydown.shift.f10="openContextMenu($event,node)" class="click-row" tabindex="0"><td><i class="mdi mdi-monitor"></i> <strong>{{node.hostname}}</strong><span v-if="node.virtualMachine" class="asset-subline">Virtual Machine</span></td><td class="mono">{{node.ip||node.fqdn||'—'}}</td><td class="os-cell"><span class="os-name">{{node.os_name||node.platform||'Unknown OS'}}</span><span v-if="node.hypervisor && node.hypervisor.toLowerCase()!==String(node.os_name||node.platform||'').toLowerCase()" class="os-hypervisor">{{node.hypervisor}}</span><span v-if="node.os_version||node.os_build" class="os-version">{{node.os_version||node.os_build}}</span></td><td>{{displayMode(node)}}<span v-if="node.agent_required" class="status pending inventory-agent-required">Agent required</span></td><td><span class="status" :class="node.ad_missing?'failed':node.ad_guid?'reachable':'unknown'">{{node.ad_missing?'AD missing':node.inventory_source||'manual'}}</span></td><td><span class="status" :class="isSnmp(node)?'reachable':firewallLabel(node).toLowerCase()">{{firewallLabel(node)}}</span></td><td><span class="status" :class="node.managementVerification?.status||'unknown'" :title="node.managementVerification?.reason||'Management check pending'">{{node.managementVerification?.label||'Unchecked'}}</span></td><td><span class="status" :class="node.status">{{node.status}}</span></td><td>{{node.last_seen_at?new Date(node.last_seen_at).toLocaleString():'Never'}}</td><td><button type="button" class="asset-menu-trigger icon-button" :aria-label="`Actions for ${node.hostname}`" title="Node actions" @click.stop="openContextMenu($event,node)"><i class="mdi mdi-dots-vertical"></i></button></td></tr><tr v-if="!nodes.length"><td colspan="10" class="empty-table">{{assetTotal?'No nodes match your filters.':'No nodes yet. Add a Windows host to begin.'}}</td></tr></tbody></table></div><div class="asset-pagination"><span>Showing {{assetTotal?((assetPage-1)*assetPageSize+1):0}}–{{Math.min(assetPage*assetPageSize,assetTotal)}} of {{assetTotal}}</span><div class="inline-actions"><button type="button" class="button small secondary" :disabled="assetPage<=1" @click="changeAssetPage(assetPage-1)">Previous</button><span>Page {{assetPage}} / {{assetTotalPages}}</span><button type="button" class="button small secondary" :disabled="assetPage>=assetTotalPages" @click="changeAssetPage(assetPage+1)">Next</button></div></div></section><section v-if="activeTab==='triage'" class="panel glass triage-panel"><div class="panel-title"><div><span class="eyebrow">DISCOVERY COVERAGE</span><h2>Unmanaged assets</h2><p class="muted">Hosts that have required an agent but have not had a successful WinRM or agent contact within {{triageWindowDays}} days of discovery.</p></div><div class="triage-summary"><span class="status pending">{{triageSummary.open}} open</span><span class="status learning">{{triageSummary.flagged}} flagged</span><span class="status unknown">{{triageSummary.excluded}} excluded</span></div></div><div class="table-tools triage-toolbar"><input v-model="triageSearch" @input="searchTriage" class="search" placeholder="Search hostname, address, OS" aria-label="Search unmanaged assets"><select v-model="triageStatus" @change="triagePage=1;loadTriage()" aria-label="Filter triage status"><option value="open">Open queue</option><option value="flagged">Flagged</option><option value="excluded">Excluded</option><option value="all">All triage records</option></select><label class="page-size">Rows <select v-model.number="triagePageSize" @change="triagePage=1;loadTriage()"><option :value="25">25</option><option :value="50">50</option><option :value="100">100</option></select></label><button class="icon-button" @click="loadTriage" title="Refresh"><i class="mdi mdi-refresh"></i></button></div><div v-if="triageNodes.length" class="triage-bulk-bar"><label class="check-label triage-page-select"><input type="checkbox" :checked="triagePageSelected" :indeterminate.prop="triagePageIndeterminate" @change="toggleTriagePage"> Select page</label><span>{{triageSelectedIds.length}} selected</span><template v-if="triageSelectedIds.length"><select v-model="triageBulkAction" aria-label="Bulk triage action"><option value="">Choose bulk action</option><option value="assign_and_retry">Assign credential and retry enrollment</option><option value="flagged">Flag selected</option><option value="excluded">Exclude selected</option><option value="none">Restore selected</option></select><select v-if="triageActionNeedsCredential()" v-model="triageBulkCredentialId" aria-label="Credential for bulk enrollment"><option value="">Choose credential</option><option v-for="credential in triageCredentials" :key="credential.id" :value="credential.id">{{credential.name}} · {{credential.type}}</option></select><button type="button" class="button small primary" :disabled="triageBulkBusy||!triageBulkAction||triageActionNeedsCredential()&&!triageBulkCredentialId" @click="runBulkTriage">{{triageBulkBusy?'Working…':'Apply to selected'}}</button><button type="button" class="button small secondary" :disabled="triageBulkBusy" @click="clearTriageSelection">Clear selection</button></template></div><div class="table-wrap"><table class="triage-table"><thead><tr><th class="triage-select-cell"><input type="checkbox" :checked="triagePageSelected" :indeterminate.prop="triagePageIndeterminate" aria-label="Select page" @change="toggleTriagePage"></th><th><button type="button" class="asset-sort" @click="sortTriage('hostname')">HOSTNAME</button></th><th><button type="button" class="asset-sort" @click="sortTriage('address')">ADDRESS</button></th><th>OS</th><th><button type="button" class="asset-sort" @click="sortTriage('status')">STATUS</button></th><th><button type="button" class="asset-sort" @click="sortTriage('firstDiscovered')">FIRST DISCOVERED</button></th><th>LAST MANAGED</th><th>TRIAGE</th><th>ONBOARDING</th><th>ACTIONS</th></tr></thead><tbody><tr v-for="node in triageNodes" :key="node.id" @click="select(node)" class="click-row"><td class="triage-select-cell" @click.stop><input type="checkbox" :checked="triageSelectedIds.includes(node.id)" :aria-label="`Select ${node.hostname}`" @change="toggleTriageSelection(node.id,$event)"></td><td><i class="mdi mdi-monitor-off"></i> <strong>{{node.hostname}}</strong></td><td class="mono">{{node.ip||node.fqdn||'—'}}</td><td class="os-cell"><span class="os-name">{{node.os_name||node.platform||'Unknown OS'}}</span><span v-if="node.os_version||node.os_build" class="os-version">{{node.os_version||node.os_build}}</span></td><td><span class="status" :class="node.status">{{node.status}}</span></td><td>{{node.firstDiscoveredAt?new Date(node.firstDiscoveredAt).toLocaleString():'—'}}</td><td>{{node.lastManagedAt?new Date(node.lastManagedAt).toLocaleString():'Never'}}</td><td><span class="status" :class="node.triageStatus==='flagged'?'learning':node.triageStatus==='excluded'?'unknown':'pending'">{{node.triageStatus==='none'?'Open':node.triageStatus}}</span><small v-if="node.triageNote">{{node.triageNote}}</small></td><td><div v-if="node.onboardingError" class="onboarding-cell"><strong>{{node.onboardingError.title}}</strong><small>{{node.onboardingError.remediation}}</small></div><span v-else>—</span></td><td><div class="inline-actions" @click.stop><button v-if="canEnroll(node)" type="button" class="button small primary" @click="beginEnrollment(node)">Enroll agent</button><button v-if="node.triageStatus!=='flagged'&&node.triageStatus!=='excluded'" type="button" class="button small secondary" @click="flagTriage(node)">Flag</button><button v-if="node.triageStatus==='flagged'||node.triageStatus==='excluded'" type="button" class="button small secondary" @click="clearTriage(node)">Restore</button><button v-if="node.triageStatus!=='excluded'" type="button" class="button small danger" @click="excludeTriage(node)">Exclude</button></div></td></tr><tr v-if="!triageNodes.length"><td colspan="10" class="empty-table">No unmanaged assets are waiting in the triage queue.</td></tr></tbody></table></div><div class="asset-pagination"><span>Showing {{triageTotal?((triagePage-1)*triagePageSize+1):0}}–{{Math.min(triagePage*triagePageSize,triageTotal)}} of {{triageTotal}}</span><div class="inline-actions"><button type="button" class="button small secondary" :disabled="triagePage<=1" @click="changeTriagePage(triagePage-1)">Previous</button><span>Page {{triagePage}} / {{triageTotalPages}}</span><button type="button" class="button small secondary" :disabled="triagePage>=triageTotalPages" @click="changeTriagePage(triagePage+1)">Next</button></div></div></section><section v-if="activeTab==='groups'" class="panel glass"><div class="panel-title"><div><span class="eyebrow">FLEET ORGANIZATION</span><h2>Node groups</h2></div><span class="count-chip">{{groups.length}} groups</span></div><div class="table-wrap"><table><thead><tr><th>GROUP</th><th>ASSETS</th><th>POLICY SCOPE</th><th>ACCESS</th><th aria-label="Actions"><span class="sr-only">Actions</span></th></tr></thead><tbody><tr v-for="group in groups" :key="group.id" class="click-row" tabindex="0" @click="openGroup(group)" @keydown.enter="openGroup(group)"><td><strong>{{group.name}}</strong><span v-if="group.dynamicEnabled" class="status pending dynamic-badge">Dynamic</span></td><td>{{group.count??group.member_count??0}}</td><td>{{group.policy_count??'—'}}</td><td>{{group.canWrite?'Editable':'Read only'}}</td><td><button type="button" class="button small secondary" @click.stop="openGroup(group)">View assets</button></td></tr><tr v-if="!groups.length"><td colspan="5" class="empty-table">No node groups yet.</td></tr></tbody></table></div></section><GlassWindow v-model="groupOpen" :title="selectedGroup?.name||'Node group'" width="700px"><div v-if="selectedGroup"><p><strong>{{selectedGroup.count}} assets</strong> in this group <span v-if="selectedGroup.dynamicEnabled" class="status pending dynamic-badge">Dynamic</span></p><p v-if="selectedGroup.dynamicEnabled" class="muted">Next refresh: {{selectedGroup.dynamicNextEvaluationAt?new Date(selectedGroup.dynamicNextEvaluationAt).toLocaleString():'Queued'}}</p><p v-if="groupError" class="error-msg" role="alert">{{groupError}}</p><DynamicGroupEditor v-if="selectedGroup.canWrite&&selectedGroup.id!=='winfire-global-all-nodes'" v-model="selectedGroupDynamic" :disabled="dynamicGroupSaving" /><div v-if="selectedGroup.canWrite&&selectedGroup.id!=='winfire-global-all-nodes'" class="form-actions"><button type="button" class="button primary" :disabled="dynamicGroupSaving" @click="saveDynamicGroup">{{dynamicGroupSaving?'Saving…':'Save dynamic rules'}}</button></div><div v-for="member in selectedGroup.members" :key="member.id" class="group-member-row"><div><strong>{{member.hostname}}</strong><small>{{member.ip||member.fqdn||'No address'}} · {{member.status}}</small></div><button v-if="canEdit&&selectedGroup.canWrite&&selectedGroup.id!=='winfire-global-all-nodes'" class="button small danger" :disabled="busy" @click="removeGroupMember(member)">Remove</button></div><p v-if="!selectedGroup.members.length" class="empty-side">No assets in this group.</p></div></GlassWindow><GlassWindow v-model="groupFormOpen" title="Add node group" width="760px"><form class="group-create-form" @submit.prevent="createGroup"><label class="group-name-field">Group name<input v-model="groupName" required maxlength="120" placeholder="Production servers" autofocus></label><nav class="admin-subtabs group-membership-tabs" role="tablist" aria-label="Node group membership type"><button type="button" role="tab" :aria-selected="groupMembershipTab==='static'" :class="{active:groupMembershipTab==='static'}" @click="selectGroupMembershipTab('static')">Static membership <span>{{staticNodeIds.length}} selected</span></button><button type="button" role="tab" :aria-selected="groupMembershipTab==='dynamic'" :class="{active:groupMembershipTab==='dynamic'}" @click="selectGroupMembershipTab('dynamic')">Dynamic rules</button></nav><section v-if="groupMembershipTab==='static'" class="group-static-panel" role="tabpanel"><div class="group-form-intro"><div><strong>Choose assets to include</strong><p>Static membership stays unchanged until an administrator edits the group.</p></div><div class="inline-actions"><button type="button" class="button small secondary" @click="selectAllStaticNodes">Select all</button><button type="button" class="button small secondary" :disabled="!staticNodeIds.length" @click="clearStaticNodes">Clear</button></div></div><div class="group-node-picker"><div v-for="node in groupCandidates" :key="node.id" class="group-node-option" :class="{selected:staticNodeIds.includes(node.id)}"><div><strong>{{node.hostname}}</strong><small>{{node.ip||node.fqdn||'No address'}} · {{node.os_name||node.platform||'Unknown OS'}}</small></div><button type="button" class="toggle-switch" :class="{active:staticNodeIds.includes(node.id)}" role="switch" :aria-checked="staticNodeIds.includes(node.id)" :aria-label="`${staticNodeIds.includes(node.id)?'Remove':'Add'} ${node.hostname}`" @click="toggleStaticNode(node.id)"><span class="toggle-track"><span></span></span><span>{{staticNodeIds.includes(node.id)?'Included':'Excluded'}}</span></button></div><p v-if="!groupCandidates.length" class="empty-side">No assets are available for static membership.</p></div></section><section v-else class="group-dynamic-panel" role="tabpanel"><p class="group-form-intro">Nodes matching these rules are added automatically and removed when they stop matching.</p><DynamicGroupEditor v-model="dynamicGroup" :show-enable="false" /></section><p v-if="error" class="error-msg" role="alert">{{error}}</p><div class="form-actions"><button type="button" class="button secondary" @click="groupFormOpen=false">Cancel</button><button class="button primary" :disabled="busy">{{busy?'Creating…':'Create node group'}}</button></div></form></GlassWindow><GlassWindow v-model="formOpen" title="Add Windows node"><form class="form-grid" @submit.prevent="create"><label>Hostname<input v-model="form.hostname" required placeholder="server-01"></label><label>FQDN<input v-model="form.fqdn" placeholder="server-01.example.com"></label><label>IP address<input v-model="form.ip" placeholder="10.0.0.5"></label><p class="training-note">New hosts train automatically for {{trainingDays}} days before learned rules are applied.</p><label>Credential<select v-model="form.credentialIds[0]" @change="preflightResult=null;preflightKey=''"><option :value="undefined">Select credential</option><option v-for="credential in credentials.filter(item=>['local','domain'].includes(item.type))" :key="credential.id" :value="credential.id">{{credential.name}}</option></select></label><div class="preflight-actions"><button type="button" class="button secondary" :disabled="preflightBusy" @click="testNewNodeConnection">{{preflightBusy?'Testing…':'Test connection'}}</button><span v-if="preflightResult" class="status" :class="preflightResult.success?'reachable':'failed'">{{preflightLabel(preflightResult)}}</span><small v-if="preflightResult?.onboardingError" class="danger-text">{{preflightResult.onboardingError.remediation}}</small></div><div class="form-actions"><button type="button" class="button secondary" @click="formOpen=false">Cancel</button><button class="button primary" :disabled="busy">{{busy?'Adding…':'Add node'}}</button></div></form></GlassWindow><GlassWindow v-model="detailOpen" :title="selected?.hostname||'Node details'" width="760px"><template v-if="selected"><div class="detail-grid"><div><span>STATUS</span><strong>{{selected.status}}</strong></div><div><span>TRANSPORT</span><strong>{{selected.transport||'Not probed'}}</strong></div><div><span>PLATFORM</span><strong>{{selected.platform||'Unknown'}}</strong><small v-if="selected.agent_required">Agent required for management</small></div><div><span>MANAGEMENT CHECK</span><strong>{{selected.managementVerification?.label||managementCheck(selected)}}</strong><small v-if="selected.transport==='wmi'&&selected.probe_status==='rpc-authenticated'">RPC sign-in passed; WMI/DCOM operations have not been verified.</small></div><div><span>ADDRESS</span><strong>{{selected.ip||selected.fqdn||'—'}}</strong></div><div><span>OS BUILD</span><strong>{{selected.os_build||selected.os_version||'Version unavailable'}}</strong></div><div><span>TTL FINGERPRINT</span><strong>{{selected.discovery_os_family||'Not observed'}}</strong><small v-if="selected.discovery_ttl">Reply TTL {{selected.discovery_ttl}}</small></div><div><span>FIREWALL STATE</span><strong>{{selected.firewall_state}}</strong></div><div><span>LAST VERIFY</span><strong :class="selected.verification?.status==='fail'?'danger-text':''">{{selected.verification?.status||'Unchecked'}}</strong></div><div><span>TRAINING ENDS</span><strong>{{selected.training?.status==='active'?new Date(selected.training.ends_at).toLocaleString():'—'}}</strong></div><div v-if="selected.virtualMachine"><span>VIRTUAL MACHINE</span><strong>Guest on {{selected.virtualMachineDetails?.hypervisorHost||'hypervisor'}}</strong><small>{{selected.virtualMachineDetails?.guestOs||selected.virtualMachineDetails?.powerState||'Guest details available'}}</small></div><div v-if="selected.hypervisor"><span>HYPERVISOR</span><strong>{{selected.hypervisor}}</strong><small>{{selected.os_version||selected.os_build||'Version unavailable'}}</small></div></div><div v-if="onboardingNotice || selected.onboardingError" class="onboarding-notice"><strong>{{(onboardingNotice||selected.onboardingError).title}}</strong><p>{{(onboardingNotice||selected.onboardingError).summary}}</p><small><b>Remediation:</b> {{(onboardingNotice||selected.onboardingError).remediation}}</small></div><section v-if="selected.virtualMachine || selected.facts?.virtualMachines?.length" class="virtualization-details"><div><span class="eyebrow">VIRTUALIZATION</span><h3>Virtual Machine / Hypervisor details</h3></div><p v-if="selected.virtualMachine" class="training-note">This asset matched a guest reported by its hypervisor inventory.</p><div v-if="selected.facts?.virtualMachines?.length" class="table-wrap"><table><thead><tr><th>VM NAME</th><th>HOSTNAME</th><th>IP</th><th>GUEST OS</th><th>POWER</th><th>CPU</th><th>MEMORY</th></tr></thead><tbody><tr v-for="vm in selected.facts.virtualMachines" :key="vm.uuid||vm.name"><td>{{vm.name}}</td><td>{{vm.hostname||'—'}}</td><td class="mono">{{vm.ip||'—'}}</td><td>{{vm.guestOs||'—'}}</td><td>{{vm.powerState||'—'}}</td><td>{{vm.cpuCount||'—'}}</td><td>{{vm.memoryMb?`${vm.memoryMb} MB`:'—'}}</td></tr></tbody></table></div><div v-else class="empty-side">No guest inventory was returned on the last authenticated hypervisor poll.</div></section><div class="inline-actions"><button class="button secondary" :disabled="busy" @click="action('probe')"><i class="mdi mdi-lan-check"></i> {{selected.hypervisor?.toLowerCase().includes('esxi')?'Refresh VM inventory':'Probe'}}</button><button v-if="canActivate(selected)" class="button secondary" :disabled="busy" @click="activateAgentless(selected)"><i class="mdi mdi-shield-check-outline"></i> Verify management</button><button class="button secondary" :disabled="busy" @click="action('facts/refresh')"><i class="mdi mdi-refresh"></i> Collect facts</button><button class="button secondary" :disabled="busy" @click="action('dns/refresh')"><i class="mdi mdi-dns"></i> Refresh DNS</button><button v-if="canEdit" class="button secondary" :disabled="busy" @click="beginEdit"><i class="mdi mdi-pencil-outline"></i> Edit node</button><button v-if="canDelete&&!selected.ad_guid" class="button danger" :disabled="busy" @click="beginDelete"><i class="mdi mdi-delete-outline"></i> Remove node</button></div><div class="training-control"><div><span class="eyebrow">HOST TRAINING</span><strong>{{selected.training?.mode==='auto'?'Automatic':selected.training?.mode==='manual'?'Manual review':'No session'}} · {{selected.training?.status||'none'}}</strong><small v-if="selected.training?.last_error">{{selected.training.last_error}}</small></div><form v-if="!['active','review','applying','apply-failed'].includes(selected.training?.status)" class="training-restart" @submit.prevent="retrain"><label>Relearn for <input v-model.number="retrainDays" type="number" min="1" max="365" required> days</label><button class="button small secondary" :disabled="busy">Start relearning</button></form><router-link v-else-if="selected.training?.status==='apply-failed'" class="button small secondary" to="/logs">Retry in Logs</router-link></div><div v-if="['winrm','winrms'].includes(selected.transport)" class="audit-readiness"><div><span class="eyebrow">TRAFFIC AUDITING</span><strong :class="auditPolicy&&!auditPolicy.successEnabled?'danger-text':''">{{auditLoading?'Checking…':auditPolicy?.successEnabled?'Filtering Platform Connection success audit enabled':auditPolicy?'Success audit disabled':'Status unknown'}}</strong><small v-if="auditPolicy&&!auditPolicy.successEnabled">Enable this audit subcategory through Group Policy before automatic training can finish. Success auditing can generate many events.</small><small v-if="auditError" class="danger-text">{{auditError}}</small></div><div class="audit-actions"><button class="button small secondary" :disabled="auditLoading" @click="loadAuditPolicy">Check again</button><button v-if="canDelete&&auditPolicy&&(!auditPolicy.successEnabled||!auditPolicy.failureEnabled)" class="button small primary" :disabled="busy" @click="beginAuditEnable">Enable auditing</button></div></div><div class="node-groups"><h3>Node groups</h3><p v-if="error" class="error-msg" role="alert">{{error}}</p><div v-for="group in selected.groups||[]" :key="group.id" class="node-group-row"><span><i class="mdi mdi-server-network"></i> {{group.name}}</span><button v-if="canEdit&&group.canWrite&&group.id!=='winfire-global-all-nodes'" class="button small secondary" :disabled="busy" :aria-label="`Remove ${selected.hostname} from ${group.name}`" @click="removeFromGroup(group)">Remove</button></div><p v-if="!selected.groups?.length" class="empty-side">This node is not in a group.</p><div v-if="canEdit&&availableGroups.length" class="inline-form"><select v-model="memberGroup" aria-label="Node group"><option value="">Select group</option><option v-for="group in availableGroups" :key="group.id" :value="group.id">{{group.name}}</option></select><button class="button small secondary" :disabled="busy||!memberGroup" @click="addToGroup">Add to group</button></div></div><div v-if="selected.probe" class="code-block">{{JSON.stringify(selected.probe,null,2)}}</div><NodeFacts :node="selected" :rule-page="rulePage" :rules-loading="rulesLoading" :rules-error="rulesError